        def __init__(
            self,
            application: Optional[Iterable[Union[str, Application]]] = None,
            externalExposure: Optional[Union[str, ExternalExposure]] = None,
            fluidSeverity: Optional[Union[str, FluidSeverity]] = None,
            fluid: Optional[Union[str, Fluid]] = None,
            inputDevice: Optional[InputDevice] = None,
            logicSolver: Optional[LogicSolver] = None,
            finalElement: Optional[FinalElement] = None,
            internalDiagnostic: Optional[
                Iterable[Union[str, InternalDiagnostic]]
            ] = None,
            externalDiagnostic: Optional[
                Iterable[Union[str, ExternalDiagnostic]]
            ] = None,
            id_short: Optional[str] = r"ReliabilityInfluencingProperties",
            display_name: Optional[aas.MultiLanguageNameType] = None,
            category: Optional[str] = None,
            description: Optional[aas.MultiLanguageTextType] = None,
            semantic_id: Optional[aas.Reference] = aas.ExternalReference(
                key=(
                    aas.Key(
                        type_=aas.KeyTypes.GLOBAL_REFERENCE,
                        value=r"https://admin-shell.io/idta/cds/ReliabilityInfluencingProperties/1",
                    ),
                ),
                referred_semantic_id=None,
            ),
            qualifier: Iterable[aas.Qualifier] = None,
            extension: Iterable[aas.Extension] = (),
            supplemental_semantic_id: Iterable[aas.Reference] = (),
            embedded_data_specifications: Iterable[
                aas.EmbeddedDataSpecification
            ] = None,
        ):

            if display_name is None:
                display_name = aas.MultiLanguageNameType(
                    dict_={r"en": r"reliability influencing property"}
                )

            if description is None:
                description = aas.MultiLanguageTextType(
                    dict_={r"en": r"reliability influencing property for the device"}
                )

            if qualifier is None:
                qualifier = (
                    aas.Qualifier(
                        type_=r"SMT/Cardinality",
                        value_type=str,
                        value=r"ZeroToOne",
                        value_id=None,
                        kind=aas.QualifierKind.TEMPLATE_QUALIFIER,
                        semantic_id=aas.ExternalReference(
                            key=(
                                aas.Key(
                                    type_=aas.KeyTypes.GLOBAL_REFERENCE,
                                    value=r"https://admin-shell.io/SubmodelTemplates/Cardinality/1/0",
                                ),
                            ),
                            referred_semantic_id=None,
                        ),
                        supplemental_semantic_id=(),
                    ),
                )

            if embedded_data_specifications is None:
                embedded_data_specifications = []

            # A str would be split into its characters
            if isinstance(application, str):
                raise TypeError("application takes several elements, got a str")

            # Build submodel elements from raw values passed in the argument
            if application:
                application = [
                    i if isinstance(i, aas.SubmodelElement) else self.Application(i)
                    for i in application
                ]

            # Build a submodel element if a raw value was passed in the argument

            if externalExposure is not None and not isinstance(
                externalExposure, aas.SubmodelElement
            ):
                externalExposure = self.ExternalExposure(externalExposure)

            # Build a submodel element if a raw value was passed in the argument

            if fluidSeverity is not None and not isinstance(
                fluidSeverity, aas.SubmodelElement
            ):
                fluidSeverity = self.FluidSeverity(fluidSeverity)

            # Build a submodel element if a raw value was passed in the argument

            if fluid is not None and not isinstance(fluid, aas.SubmodelElement):
                fluid = self.Fluid(fluid)

            # A str would be split into its characters
            if isinstance(internalDiagnostic, str):
                raise TypeError("internalDiagnostic takes several elements, got a str")

            # Build submodel elements from raw values passed in the argument
            if internalDiagnostic:
                internalDiagnostic = [
                    (
                        i
                        if isinstance(i, aas.SubmodelElement)
                        else self.InternalDiagnostic(i)
                    )
                    for i in internalDiagnostic
                ]

            # A str would be split into its characters
            if isinstance(externalDiagnostic, str):
                raise TypeError("externalDiagnostic takes several elements, got a str")

            # Build submodel elements from raw values passed in the argument
            if externalDiagnostic:
                externalDiagnostic = [
                    (
                        i
                        if isinstance(i, aas.SubmodelElement)
                        else self.ExternalDiagnostic(i)
                    )
                    for i in externalDiagnostic
                ]

            # Add all passed/initialized submodel elements to a single list
            embedded_submodel_elements = []
            for se_arg in [
                application,
                externalExposure,
                fluidSeverity,
                fluid,
                inputDevice,
                logicSolver,
                finalElement,
                internalDiagnostic,
                externalDiagnostic,
            ]:
                if se_arg is None:
                    continue
                elif isinstance(se_arg, aas.SubmodelElement):
                    embedded_submodel_elements.append(se_arg)
                elif isinstance(se_arg, Iterable):
                    for n, element in enumerate(se_arg):
                        element.id_short = f"{element.id_short}{n}"
                        embedded_submodel_elements.append(element)
                else:
                    raise TypeError(
                        f"Unknown type of value in submodel_element_args: {se_arg.__class__}"
                    )

            super().__init__(
                value=embedded_submodel_elements,
                id_short=id_short,
                display_name=display_name,
                category=category,
                description=description,
                semantic_id=semantic_id,
                qualifier=qualifier,
                extension=extension,
                supplemental_semantic_id=supplemental_semantic_id,
                embedded_data_specifications=embedded_data_specifications,
            )

